function brief(n, d) {
  if (!n) return null;
  const o = { id: n.id, name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height) };
  if (d > 0 && 'children' in n && n.children) o.children = n.children.map(c => brief(c, d - 1));
  if (n.type === 'TEXT') { o.chars = n.characters; o.font = n.fontName && n.fontName.style ? n.fontName.family + ' ' + n.fontName.style : 'mixed'; o.size = n.fontSize; o.fill = (n.fills && n.fills[0] && n.fills[0].type === 'SOLID') ? JSON.stringify(n.fills[0].color) : 'other'; }
  if ('fills' in n && n.fills && n.fills.length) {
    const f = n.fills[0];
    if (f.type === 'SOLID') o.fill = JSON.stringify(f.color);
    else if (f.type === 'IMAGE') o.image = f.imageHash + ' scale=' + f.scaleMode;
  }
  if ('cornerRadius' in n && typeof n.cornerRadius === 'number') o.radius = n.cornerRadius;
  if ('strokes' in n && n.strokes && n.strokes.length) o.stroke = JSON.stringify(n.strokes[0].color || n.strokes[0].type);
  return o;
}
