  const nodes=[root].concat('children' in root ? root.findAll(()=>true) : []);
  for (const n of nodes){
    try{
      if('fills' in n && Array.isArray(n.fills) && n.fills.length && n.fills.every(f=>f&&f.type==='SOLID'))
        n.fills=n.fills.map(f=>({type:'SOLID',color:hex,opacity:f.opacity===undefined?1:f.opacity}));
      if('strokes' in n && Array.isArray(n.strokes) && n.strokes.length && n.strokes.every(s=>s&&s.type==='SOLID'))
        n.strokes=n.strokes.map(s=>({type:'SOLID',color:hex,opacity:s.opacity===undefined?1:s.opacity}));
    }catch(e){}
  }
}
