function link(node,dest,transition){
  node.reactInterractions=[{trigger:{type:'ON_TAP'},action:{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:transition||{type:'DISSOLVE',duration:0.25}}}];
}
function hotspot(parent,x,y,w,h,dest,transition){
  const r=figma.createRectangle(); r.name='Hotspot'; r.resize(w,h); r.x=x; r.y=y; r.fills=[];
  parent.appendChild(r); link(r,dest,transition); return r;
}
const splash=await gid('2007:30'), welcome=await gid('2007:49'), empty=await gid('2007:71'),
      filled=await gid('2007:104'), error=await gid('2007:135'), home=await gid('2009:113'),
      overlay=await gid('2013:229'), notif=await gid('2013:314'), profile=await gid('2012:166'),
      contact=await gid('2014:337'), bank=await gid('2014:386');

